@Composable
fun GIcon(
    v: ImageVector,
    modifier: Modifier = Modifier,
    size: Dp = 22.dp,
    tint: Color = Gx.text,
) {
    Icon(imageVector = v, contentDescription = null, modifier = modifier.size(size), tint = tint)
}